  return run;
}

/* ── Award gold + survivors for a run that completed while the tab was away ── */
function _resolveReturnedRun(run) {
  const innBonus = Object.values(state.locs).reduce((s, l) => s + l.level, 0);
  const bonus    = Math.floor(12 + run.floor * 8 + innBonus * 2);
  const gold     = run.goldEarned + bonus;
  setGold(state.gold + gold);
  addLog(
    ` [${_partyLabel(run)}] Returned while you were away! ` +
    `${run.defeatedCount} slain · ${gold}g earned.`,
    'gold'
  );
  const survivors = run.party.filter(m => m.status !== 'incapacitated');
  if (survivors.length > 0) addReturningAdventurers(survivors);
}

/* ── Restore full game state from localStorage; returns true on success ── */
function loadState() {
  let data;
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return false;
    data = JSON.parse(raw);
  } catch (e) {
    console.warn('[DungeInnMaster] Could not parse save data:', e);
    return false;
  }
  if (!data || data.version !== SAVE_VERSION) return false;

  // Gold
  setGold(data.gold ?? 50);

  // Inn locations
  if (data.locs) {
    for (const id of Object.keys(state.locs)) {
      if (data.locs[id]) {
        state.locs[id] = data.locs[id];
        refreshLocation(id);
      }
    }
  }

  // Applicant pool (including returning veterans)
  if (Array.isArray(data.applicants)) {
    applicants            = data.applicants;
    _applicantRosterLevel = data.applicantRosterLevel ?? -1;
  }

  // Active runs
  if (Array.isArray(data.activeRuns)) {
    data.activeRuns.forEach(snap => {
      if (!snap || snap.phase === 'done') return;
      _restoreRun(snap, data.savedAt);
    });
  }

  refreshInnExpeditionStatus();
  addLog(' Game restored from your last session.', '');
  // Persist immediately so resolved/stale runs are scrubbed from the save file
  scheduleSave();
  return true;
}

/* ── Wipe the save and reload for a clean slate ── */
function resetSave() {
  if (!confirm('⚠️ Reset all progress and start fresh?')) return;
  localStorage.removeItem(SAVE_KEY);
  location.reload();
}

/* ═══════════════════════════════════════════════════════
   ADVENTURE.UI.JS — Adventure page DOM rendering and
   overlay management.  Also exposes watchRun / stopWatching
   which the game engine calls via typeof guard.
═══════════════════════════════════════════════════════ */

/* ── Attach the renderer canvas and switch to the adventure page ── */
function watchRun(runId) {
  if (state.watchingRunId && state.watchingRunId !== runId) {
    const prev = state.activeRuns.find(r => r.id === state.watchingRunId);
    if (prev) prev.renderer?.detach();
  }
  state.watchingRunId = runId;
  const run = state.activeRuns.find(r => r.id === runId);
  if (!run) return;
  run.renderer?.attach(document.getElementById('dungeon-canvas'));
  showPage('adventure-page');
  document.getElementById('outcome-overlay').classList.add('hidden');
  const restOverlay = document.getElementById('rest-overlay');
  if (restOverlay) {
    if (run.phase === 'resting') _showRestOverlay(run);
    else restOverlay.classList.add('hidden');
  }
  updateAdventureUI(run);
}

/* ── Detach renderer and return to the inn page ── */
function stopWatching() {
  if (state.watchingRunId) {
    const run = state.activeRuns.find(r => r.id === state.watchingRunId);
    if (run) run.renderer?.detach();
  }
  state.watchingRunId = null;
  _hideRestOverlay();
  showPage('inn-page');
  refreshInfoPanel();
  refreshInnExpeditionStatus();
}

/* ── Populate and show the rest-room overlay ── */
function _showRestOverlay(run) {
  const overlay = document.getElementById('rest-overlay');
  if (!overlay || state.watchingRunId !== run.id) return;
  const el = id => document.getElementById(id);
  if (el('rest-floor-num'))      el('rest-floor-num').textContent      = run.floor;
  if (el('rest-next-floor'))     el('rest-next-floor').textContent     = run.floor + 1;
  const fmtReturn = _fmtMs(run.returnDuration);
  if (el('rest-return-time'))     el('rest-return-time').textContent     = fmtReturn;
  if (el('rest-return-time-btn')) el('rest-return-time-btn').textContent = fmtReturn;
  overlay.classList.remove('hidden');
}

/* ── Hide the rest-room overlay ── */
function _hideRestOverlay() {
  document.getElementById('rest-overlay')?.classList.add('hidden');
}

/* ── Populate and show the outcome overlay ── */
function _showOutcomeOverlay(icon, title, msg) {
  document.getElementById('outcome-icon').textContent  = icon;
  document.getElementById('outcome-title').textContent = title;
  document.getElementById('outcome-msg').textContent   = msg;
  document.getElementById('outcome-overlay').classList.remove('hidden');
}

/* ── Full adventure-page refresh for the currently watched run ── */
function updateAdventureUI(run) {
  if (!run || state.watchingRunId !== run.id) return;
  if (document.getElementById('adventure-page').classList.contains('hidden')) return;

  const now = Date.now();
  let pct = 0, floorLabelText = '', timeText = '';

  if (run.phase === 'returning') {
    if (run.returnDuration > 0) {
      pct = Math.min(100, ((now - run.returnStartTime) / run.returnDuration) * 100);
      timeText = '↩ ' + _fmtMs(Math.max(0, run.returnDuration - (now - run.returnStartTime)));
    } else { pct = 100; timeText = '↩ …'; }
    floorLabelText = `Floor ${run.floor} — Returning`;
  } else if (run.phase === 'resting') {
    pct = 100;
    floorLabelText = `Floor ${run.floor} Complete! ️`;
    timeText = '️ Rest';
  } else {
    pct = Math.min(100, (run.encRoomsCleared / ROOMS_PER_FLOOR) * 100);
    floorLabelText = run.encRoomsCleared >= ROOMS_PER_FLOOR
      ? `Floor ${run.floor} Complete! ️`
      : `Floor ${run.floor} — Room ${run.encRoomsCleared + 1}/${ROOMS_PER_FLOOR}`;
    timeText = _fmtMs(now - run.floorStartTime);
  }

  const fillEl = document.getElementById('floor-progress-fill');
  if (fillEl) fillEl.style.width = pct.toFixed(1) + '%';
  const floorLabelEl = document.getElementById('floor-label');
  if (floorLabelEl) floorLabelEl.textContent = floorLabelText;
  const timeEl = document.getElementById('floor-time-left');
  if (timeEl) timeEl.textContent = timeText;

  const cntEl = document.getElementById('enc-count');
  if (cntEl) cntEl.textContent = run.defeatedCount;

  const enc = run.encounterActive ? run.currentEncounter : null;
  if (enc) {
    document.getElementById('enc-icon').textContent = enc.icon;
    document.getElementById('enc-name').textContent = enc.name;
    document.getElementById('enc-diff').textContent = 'Difficulty: '+'★'.repeat(Math.ceil(enc.difficulty/5));
    document.getElementById('enc-desc').textContent = enc.desc;
  } else {
    const icons = { returning:'', done:'✅', traveling:'️', resting:'️' };
    document.getElementById('enc-icon').textContent = icons[run.phase] ?? '️';
    document.getElementById('enc-name').textContent = _phaseTitle(run);
    document.getElementById('enc-diff').textContent = '';
    document.getElementById('enc-desc').textContent = _phaseDesc(run);
  }

  renderAdvParty(run);
  document.getElementById('run-gold-earned').textContent = run.goldEarned;
  document.getElementById('adv-status').textContent = _phaseDesc(run);
  const recallBtn = document.getElementById('recall-btn');
  if (recallBtn) {
    recallBtn.disabled = run.phase === 'done' || run.phase === 'returning' || run.phase === 'resting';
  }
}

/* ── Party member cards in the adventure page ── */
function renderAdvParty(run) {
  const container = document.getElementById('adv-party');
  if (!container) return;
  const now = Date.now();

  run.party.forEach((m, idx) => {
    const hpPct   = Math.max(0, Math.round((m.hp/m.maxHp)*100));
    const hpColor = hpPct>55?'#4ac96a':hpPct>28?'#e9c84a':'#e94560';
    const used    = run.abilitiesUsed.has(m.id);
    const incap   = m.status === 'incapacitated';
    const canUse  = !used && !incap && run.phase !== 'returning' && run.phase !== 'done';
    const buff    = run.activeBuffs.find(b => b.memberId===m.id && b.expiresAt>now);

    let card = container.children[idx];
    if (!card || card.dataset.memberId !== m.id) {
      card = document.createElement('div');
      card.dataset.memberId = m.id;
      card.innerHTML = `
        <div class="adv-member-icon">${m.cls.icon}</div>
        <div class="adv-member-name">${m.name.split(' ')[0]}</div>
        <span class="rarity-badge ${m.rarity.cls}">${m.rarity.label}</span>
        <div class="hp-row">
          <div class="hp-bar-bg"><div class="hp-bar-fill"></div></div>
          <span class="hp-value"></span>
        </div>
        <div class="buff-timer" style="display:none">
          <div class="buff-bar-bg"><div class="buff-bar-fill"></div></div>
          <span class="buff-label"></span>
        </div>
        <button class="ability-btn" title="${m.cls.ability.desc}">
          ✦ ${m.cls.ability.name}
        </button>`;
      card.querySelector('.ability-btn').addEventListener('click', () => useAbility(run.id, m.id));
      if (container.children[idx]) {
        container.replaceChild(card, container.children[idx]);
      } else {
        container.appendChild(card);
      }
    }

    card.className = `adv-member ${m.status}`;

    const hpFill = card.querySelector('.hp-bar-fill');
    if (hpFill) { hpFill.style.width = hpPct + '%'; hpFill.style.background = hpColor; }
    const hpVal = card.querySelector('.hp-value');
    if (hpVal) hpVal.textContent = `${Math.max(0,m.hp)}/${m.maxHp}`;

    const buffTimer = card.querySelector('.buff-timer');
    if (buffTimer) {
      if (buff) {
        const dur = ABILITY_DURATION_MS[m.rarity.id] ?? ABILITY_DURATION_MS.common;
        const bp  = Math.max(0, ((buff.expiresAt-now)/dur)*100).toFixed(1);
        buffTimer.style.display = '';
        const bFill = buffTimer.querySelector('.buff-bar-fill');
        if (bFill) bFill.style.width = bp + '%';
        const bLbl = buffTimer.querySelector('.buff-label');
        if (bLbl) bLbl.textContent = `${buff.label} ${_fmtMs(buff.expiresAt-now)}`;
      } else {
        buffTimer.style.display = 'none';
      }
    }

    const btn = card.querySelector('.ability-btn');
    if (btn) btn.disabled = !canUse;
  });

  while (container.children.length > run.party.length) {
    container.removeChild(container.lastChild);
  }
}

/* ── Called by adventure.js when dungeon page needs a refresh ── */
function _updateDungeonPageIfVisible() {
  if (!document.getElementById('dungeon-page').classList.contains('hidden')) {
    renderActiveRuns();
    updateVentureBtn();
  }
}

/* ── Called by adventure.js to push UI updates for the watched run ── */
function _updateAdventureUIIfWatching(run) {
  if (state.watchingRunId === run.id) updateAdventureUI(run);
}

/* ── Sub-second UI refresh for smooth progress bars and timers ── */
setInterval(() => {
  if (!state.watchingRunId) return;
  const run = state.activeRuns.find(r => r.id === state.watchingRunId);
  if (run && !document.getElementById('adventure-page').classList.contains('hidden'))
    updateAdventureUI(run);
}, 500);

/* ═══════════════════════════════════════════════════════
   API.JS — Game action abstraction layer
   All game mutations flow through this object.

   API_MODE = 'local'  → calls server/game functions directly
                         (current browser-only mode)
   API_MODE = 'remote' → replaces each call with fetch() to
                         the Express endpoints in server/routes/

   Switch to 'remote' once server/app.js is running.
═══════════════════════════════════════════════════════ */

const API_MODE = 'local'; // 'local' | 'remote'

const API = (() => {

  /* ── Shared fetch helper for the remote path ── */
  async function _post(path, body = {}) {
    const res = await fetch(path, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify(body),
    });
    if (!res.ok) throw new Error(`API error ${res.status} on ${path}`);
    return res.json();
  }
  async function _get(path) {
    const res = await fetch(path);
    if (!res.ok) throw new Error(`API error ${res.status} on ${path}`);
    return res.json();
  }

  /* ══════════════════════════════
     INN
  ══════════════════════════════ */
  const inn = {
    /** Upgrade a location. Returns { success, locationId, level, gold } */
    upgrade(locationId) {
      if (API_MODE === 'local') {
        const result = doUpgrade(locationId);
        if (result.success) {
          refreshLocation(result.locationId);
          refreshInfoPanel();
        }
        return Promise.resolve(result);
      }
      return _post(`/api/inn/upgrade/${locationId}`)
        .then(result => {
          if (result.success) { refreshLocation(result.locationId); refreshInfoPanel(); }
          return result;
        });
    },

    /** Current inn state snapshot { gold, locs } */
    getState() {
      if (API_MODE === 'local') return Promise.resolve({ gold: state.gold, locs: state.locs });
      return _get('/api/inn/state');
    },

    /** Projected income per tick */
    getIncome() {
      if (API_MODE === 'local') return Promise.resolve({ income: getInnIncome() });
      return _get('/api/inn/income');
    },
  };

  /* ══════════════════════════════
     DUNGEON
  ══════════════════════════════ */
  const dungeon = {
    /** Current applicants and party { applicants, partyIds, rosterLevel } */
    getApplicants() {
      if (API_MODE === 'local') return Promise.resolve({ applicants, partyIds, rosterLevel: _applicantRosterLevel });
      return _get('/api/dungeon/applicants');
    },

    /** Re-roll the applicant roster */
    reroll() {
      if (API_MODE === 'local') return Promise.resolve(rerollApplicants());
      return _post('/api/dungeon/reroll');
    },

    /** Hire or remove a member (toggles) */
    hire(memberId) {
      if (API_MODE === 'local') return Promise.resolve(toggleMember(memberId));
      return _post(`/api/dungeon/hire/${memberId}`);
    },

    /** Remove all members from the party */
    clearParty() {
      if (API_MODE === 'local') return Promise.resolve(clearParty());
      return _post('/api/dungeon/clear');
    },

    /** Deploy the current party into the dungeon */
    deploy() {
      if (API_MODE === 'local') {
        if (partyIds.length < 1) return Promise.resolve({ success: false, reason: 'empty_party' });
        if (state.activeRuns.length >= maxParties()) return Promise.resolve({ success: false, reason: 'hearth_full' });
        const party = getParty();
        postDeploy();
        const run = startRun(party);
        return Promise.resolve({ success: true, runId: run.id });
      }
      return _post('/api/dungeon/deploy');
    },
  };

  /* ══════════════════════════════
     ADVENTURE
  ══════════════════════════════ */
  const adventure = {
    /** Serialisable snapshot of all active runs */
    getRuns() {
      if (API_MODE === 'local') return Promise.resolve(state.activeRuns.map(r => ({
        id: r.id, phase: r.phase, floor: r.floor,
        goldEarned: r.goldEarned, defeatedCount: r.defeatedCount,
        party: r.party.map(m => ({ id: m.id, name: m.name, status: m.status, hp: m.hp, maxHp: m.maxHp })),
      })));
      return _get('/api/adventure/runs');
    },

    /** Recall the party of the given run */
    recall(runId) {
      if (API_MODE === 'local') { recallParty(); return Promise.resolve({ success: true }); }
      return _post(`/api/adventure/recall/${runId}`);
    },

    /** Descend to the next floor */
    descend(runId) {
      if (API_MODE === 'local') { descendFloor(runId); return Promise.resolve({ success: true }); }
      return _post(`/api/adventure/descend/${runId}`);
    },

    /** Return to the inn from the rest room */
    returnToInn(runId) {
      if (API_MODE === 'local') { returnFromRest(runId); return Promise.resolve({ success: true }); }
      return _post(`/api/adventure/return/${runId}`);
    },

    /** Activate a member's ability */
    useAbility(runId, memberId) {
      if (API_MODE === 'local') { useAbility(runId, memberId); return Promise.resolve({ success: true }); }
      return _post(`/api/adventure/ability/${runId}/${memberId}`);
    },
  };

  return { inn, dungeon, adventure };
})();

/* ═══════════════════════════════════════════════════════
   DUNGEON.UI.JS — Dungeon / party-selection page rendering
   Depends on: server/game/dungeon.js, server/game/state.js
═══════════════════════════════════════════════════════ */

/* ── Sort preference lives in UI state, not game state ── */
let applicantSort = 'default';
let _sortBarReady = false;

/* ── Navigate to the dungeon gate page ── */
function showDungeonPage() {
  showPage('dungeon-page');
  _initSortBar();
  refreshDungeonPage();
}

/* ── Wire sort buttons once ── */
function _initSortBar() {
  if (_sortBarReady) return;
  _sortBarReady = true;
  const bar = document.getElementById('sort-bar');
  if (!bar) return;
  bar.addEventListener('click', e => {
    const btn = e.target.closest('.sort-btn');
    if (!btn) return;
    applicantSort = btn.dataset.sort;
    bar.querySelectorAll('.sort-btn').forEach(b => b.classList.toggle('active', b === btn));
    renderApplicantGrid();
  });
}

/* ── Full dungeon page refresh ── */
function refreshDungeonPage() {
  renderActiveRuns();

  const canDeploy     = state.activeRuns.length < maxParties();
  const deploySection = document.getElementById('deploy-section');
  const limitMsg      = document.getElementById('hearth-limit-msg');

  if (canDeploy) {
    if (deploySection) deploySection.style.display = '';
    if (limitMsg) limitMsg.textContent = '';

    if (applicants.length === 0) {
      _generateApplicants();
    } else {
      _topUpApplicants();
    }

    renderPartySlots();
    renderApplicantGrid();
    updateVentureBtn();
  } else {
    if (deploySection) deploySection.style.display = 'none';
    if (limitMsg) limitMsg.textContent =
      ` Hearth limit reached (${state.activeRuns.length}/${maxParties()} parties). Upgrade the Hearth to deploy more.`;
  }
}

/* ── Active expeditions panel ── */
function renderActiveRuns() {
  const container = document.getElementById('active-runs-container');
  if (!container) return;

  if (state.activeRuns.length === 0) {
    container.innerHTML = '<p class="no-runs-msg">No active expeditions — deploy a party to begin!</p>';
    return;
  }

  container.innerHTML = '';
  state.activeRuns.forEach(run => {
    const card = document.createElement('div');
    card.className = 'run-card';

    const alive = run.party.filter(m => m.status !== 'incapacitated').length;
    const total = run.party.length;
    const icons = run.party.map(m =>
      `<span class="run-member-icon ${m.status==='incapacitated'?'dead':m.status==='wounded'?'wounded':''}">${m.cls.icon}</span>`
    ).join('');

    const enc        = run.currentEncounter;
    const phaseIcons = { traveling:'', returning:'', done:'✅', resting:'️' };
    const phaseIcon  = phaseIcons[run.phase] ?? '';
    const phaseText  = enc && run.encounterActive
      ? `${enc.icon} ${enc.name}`
      : ({ traveling: run.encRoomsCleared >= ROOMS_PER_FLOOR
                        ? `️ F${run.floor} cleared`
                        : `F${run.floor} · Rm ${run.encRoomsCleared + 1}/${ROOMS_PER_FLOOR}`,
           resting:   `️ F${run.floor} cleared`,
           returning: 'Returning',
           done:      'Done' }[run.phase] ?? `Floor ${run.floor}`);

    const bar = run.phase === 'returning' && run.returnDuration > 0
      ? Math.min(100, ((Date.now() - run.returnStartTime) / run.returnDuration) * 100).toFixed(0)
      : Math.min(100, (run.encRoomsCleared / ROOMS_PER_FLOOR) * 100).toFixed(0);

    card.innerHTML = `
      <div class="run-card-icons">${icons}</div>
      <div class="run-card-info">
        <div class="run-card-phase">${phaseIcon} ${phaseText}</div>
        <div class="run-card-stats"> ${alive}/${total} alive &nbsp;·&nbsp;  ${run.goldEarned}g</div>
        <div class="run-mini-bar-bg"><div class="run-mini-bar-fill" style="width:${bar}%"></div></div>
      </div>
      <button class="watch-btn"> Watch</button>`;
    card.querySelector('.watch-btn').addEventListener('click', () => watchRun(run.id));
    container.appendChild(card);
  });
}

/* ── Applicant card grid ── */
function renderApplicantGrid() {
  const grid = document.getElementById('applicant-grid');
  if (!grid) return;
  grid.innerHTML = '';

  _updateApplicantLabel();

  const sorted = [...applicants];
  if (applicantSort === 'rarity') {
    sorted.sort((a, b) => RARITIES.findIndex(r => r.id === b.rarity.id) - RARITIES.findIndex(r => r.id === a.rarity.id));
  } else if (applicantSort === 'class') {
    sorted.sort((a, b) => a.cls.name.localeCompare(b.cls.name));
  } else if (applicantSort === 'power') {
    sorted.sort((a, b) => b.power - a.power);
  } else {
    sorted.sort((a, b) => (b.returning ? 1 : 0) - (a.returning ? 1 : 0));
  }

  sorted.forEach(app => {
    if (partyIds.includes(app.id)) return;
    const cost       = _hireCost(app);
    const affordable = app.returning || state.gold >= cost;
    const card = document.createElement('div');
    card.className = `applicant-card${affordable ? '' : ' unaffordable'}${app.returning ? ' returning-veteran' : ''}`;
    const pct = Math.round((app.power / 25) * 100);
    card.innerHTML = `
      <div class="app-icon">${app.cls.icon}</div>
      <div class="app-name">${app.name}</div>
      <div class="app-class">${app.cls.name}</div>
      <span class="rarity-badge ${app.rarity.cls}">${app.rarity.label}</span>
      <div class="app-ability" title="${app.cls.ability.desc}">✦ ${app.cls.ability.name}</div>
      <div class="power-row">
        <span class="power-label">PWR</span>
        <div class="power-bar-bg"><div class="power-bar-fill" style="width:${pct}%"></div></div>
        <span class="power-value">${app.power}</span>
      </div>
      <div class="app-cost${affordable ? '' : ' unaffordable'}">${app.returning ? ' Free' : ` ${cost}g`}</div>`;
    card.addEventListener('click', () => toggleMember(app.id));
    card.draggable = true;
    card.addEventListener('dragstart', e => {
      e.dataTransfer.setData('text/plain', app.id);
      e.dataTransfer.effectAllowed = 'move';
      setTimeout(() => card.classList.add('dragging'), 0);
    });
    card.addEventListener('dragend', () => card.classList.remove('dragging'));
    grid.appendChild(card);
  });
}

/* ── Party slot row ── */
function renderPartySlots() {
  const slotsEl = document.getElementById('party-slots');
  if (!slotsEl) return;
  slotsEl.innerHTML = '';
  for (let i = 0; i < 4; i++) {
    const memberId = partyIds[i];
    const member   = memberId ? applicants.find(a => a.id === memberId) : null;
    const slot     = document.createElement('div');
    slot.className = `party-slot ${member ? 'filled' : 'empty'}`;
    if (member) {
      slot.style.borderColor = member.rarity.color;
      slot.innerHTML = `
        <span class="slot-remove" title="Remove">✕</span>
        <div class="slot-icon">${member.cls.icon}</div>
        <div class="slot-name">${member.name.split(' ')[0]}</div>
        <span class="rarity-badge ${member.rarity.cls}" style="font-size:0.5rem">${member.rarity.label}</span>`;
      slot.querySelector('.slot-remove').addEventListener('click', e => {
        e.stopPropagation(); toggleMember(memberId);
      });
      slot.draggable = true;
      slot.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', memberId);
        e.dataTransfer.effectAllowed = 'move';
        setTimeout(() => slot.classList.add('dragging'), 0);
      });
      slot.addEventListener('dragend', () => slot.classList.remove('dragging'));
    } else {
      slot.innerHTML = `<div class="slot-empty">Drop here</div>`;
    }
    slot.addEventListener('dragover',  e => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; });
    slot.addEventListener('dragenter', e => { e.preventDefault(); slot.classList.add('drag-over'); });
    slot.addEventListener('dragleave', e => { if (!slot.contains(e.relatedTarget)) slot.classList.remove('drag-over'); });
    slot.addEventListener('drop', e => {
      e.preventDefault();
      slot.classList.remove('drag-over');
      const draggedId = e.dataTransfer.getData('text/plain');
      if (draggedId) _dropOnSlot(draggedId, i);
    });
    slotsEl.appendChild(slot);
  }
  const pc = document.getElementById('party-count');
  if (pc) pc.textContent = partyIds.length;
}

/* ── Update the applicant count label ── */
function _updateApplicantLabel() {
  const lbl = document.getElementById('applicant-label');
  if (!lbl) return;
  const available = applicants.filter(a => !partyIds.includes(a.id)).length;
  lbl.textContent = `Adventurers seeking work — Guest Room Lv ${_applicantRosterLevel} (${available} available)`;
}

/* ── Venture button state ── */
function updateVentureBtn() {
  const btn = document.getElementById('venture-btn');
  if (!btn) return;

  if (state.activeRuns.length >= maxParties()) {
    btn.disabled = true;
    btn.textContent = ` Hearth limit (${state.activeRuns.length}/${maxParties()})`;
    _updateRerollBtn();
    return;
  }

  const count = partyIds.length;
  const ps    = document.getElementById('party-status');
  if (count >= 1) {
    btn.disabled = false;
    const totalPower = partyIds.reduce((s, id) => s + (applicants.find(a => a.id === id)?.power ?? 0), 0);
    const slots = count === 4 ? 'full party' : `${count} member${count > 1 ? 's' : ''}`;
    btn.textContent = `⚔️ Venture Forth! (${slots} · Power: ${totalPower})`;
    if (ps) ps.textContent = count < 4
      ? `Ready! You may add up to ${4 - count} more member${4 - count > 1 ? 's' : ''}, or venture now.`
      : 'Your party is ready. Steel yourselves!';
  } else {
    btn.disabled = true;
    btn.textContent = 'Select 1–4 Adventurers';
    if (ps) ps.textContent = 'Choose 1–4 adventurers from the list below.';
  }
  _updateRerollBtn();
}

/* ── Re-roll button label and affordability ── */
function _updateRerollBtn() {
  const btn = document.getElementById('reroll-btn');
  if (!btn) return;
  const cost          = _rerollCost();
  const affordableGold = state.gold + _partyRefundTotal();
  btn.textContent = ` Re-roll (${cost}g)`;
  btn.disabled    = affordableGold < cost;
}

/* ═══════════════════════════════════════════════════════
   INN.UI.JS — Inn page DOM rendering
   Depends on: server/game/state.js, server/game/inn.js,
               server/game/data.js, client/js/ui-helpers.js
═══════════════════════════════════════════════════════ */

function refreshLocation(id) {
  const el  = document.querySelector(`.location[data-id="${id}"]`);
  const lvl = state.locs[id].level;
  for (let i = 0; i <= MAX_LVL; i++) el.classList.remove(`lv${i}`);
  if (lvl > 0) el.classList.add(`lv${lvl}`);
  el.querySelector('.loc-level').textContent = `Lv ${lvl}${lvl === MAX_LVL ? ' ★' : ''}`;
}

function refreshInfoPanel() {
  const infoEl = document.getElementById('info-panel');
  const id = state.selected;
  if (!id) {
    infoEl.innerHTML = '<p class="welcome-msg">Welcome, Inn Keeper! Select a location to manage it, or venture into the dungeon for gold.</p>';
    return;
  }
  const def  = DEFS[id], lvl = state.locs[id].level;
  const cost = upgradeCost(id), maxed = lvl >= MAX_LVL;
  const pips = Array.from({ length: MAX_LVL }, (_, i) =>
    `<div class="level-pip ${i < lvl ? 'filled' : ''}"></div>`).join('');
  infoEl.innerHTML = `
    <div class="info-content">
      <div class="info-title">${def.icon} ${def.name}</div>
      <div class="info-desc">${def.desc}</div>
      <div class="info-stats">Level ${lvl} / ${MAX_LVL} &nbsp;·&nbsp; Earns ${def.income * lvl} gold / tick</div>
      <div class="level-bar">${pips}</div>
    </div>
    <button class="upgrade-btn" id="upgrade-btn" ${maxed || state.gold < cost ? 'disabled' : ''}>
      ${maxed ? '★ Maxed Out' : `Upgrade<br><small>${cost} Gold</small>`}
    </button>`;
  if (!maxed) {
    document.getElementById('upgrade-btn').addEventListener('click', () => doUpgrade(id));
  }
}

function selectLocation(id) {
  document.querySelectorAll('.location').forEach(el => el.classList.remove('selected'));
  state.selected = (state.selected === id) ? null : id;
  if (state.selected) document.querySelector(`.location[data-id="${id}"]`).classList.add('selected');
  refreshInfoPanel();
}

/* ── Active expedition pills on the inn page ── */
function refreshInnExpeditionStatus() {
  const el = document.getElementById('inn-expedition-status');
  if (!el) return;

  if (!state.activeRuns || state.activeRuns.length === 0) {
    el.innerHTML = '';
    return;
  }

  const liveIds = new Set(state.activeRuns.map(r => r.id));
  el.querySelectorAll('.inn-run-pill').forEach(p => {
    if (!liveIds.has(p.dataset.runId)) p.remove();
  });

  state.activeRuns.forEach(run => {
    const alive = run.party.filter(m => m.status !== 'incapacitated').length;
    const phaseIcons = { traveling:'', returning:'', done:'✅', resting:'️' };
    const pIcon = phaseIcons[run.phase] ?? '';
    const label = (run.party[0]?.name.split(' ')[0] ?? 'Party') + "'s party";

    let pill = el.querySelector(`.inn-run-pill[data-run-id="${run.id}"]`);
    if (!pill) {
      pill = document.createElement('div');
      pill.className = 'inn-run-pill';
      pill.dataset.runId = run.id;
      pill.title = 'Click to watch this expedition';
      pill.addEventListener('click', () => watchRun(run.id));
      el.appendChild(pill);
    }
    pill.innerHTML = `${pIcon} ${label} F${run.floor} &nbsp;${alive} &nbsp;${run.goldEarned}g`;
  });
}

/* ── Wire location clicks ── */
document.querySelectorAll('.location').forEach(el =>
  el.addEventListener('click', () => selectLocation(el.dataset.id)));

/* ═══════════════════════════════════════════════════════
   MAIN.JS — App entry point: event wiring only.
   All game actions are dispatched through the API object.
   Load order: last, after all game + UI scripts.
═══════════════════════════════════════════════════════ */

/* ── Inn page ── */
document.getElementById('dungeon-btn').addEventListener('click', showDungeonPage);

/* ── Log expand / collapse ── */
document.querySelectorAll('.log-toggle').forEach(btn => {
  btn.addEventListener('click', () => {
    const log = document.getElementById(btn.dataset.target);
    if (!log) return;
    const expanded = log.classList.toggle('expanded');
    btn.classList.toggle('active', expanded);
    if (expanded) {
      btn.textContent = btn.textContent.replace('▾', '▴').replace('expand', 'collapse');
      log.scrollTop = log.scrollHeight;
    } else {
      btn.textContent = btn.textContent.replace('▴', '▾').replace('collapse', 'expand');
    }
  });
});

/* ── Combat log filters ── */
document.querySelectorAll('.log-filter').forEach(btn => {
  btn.addEventListener('click', () => {
    const log = document.getElementById(btn.dataset.log);
    if (!log) return;
    const nowActive = btn.classList.toggle('active');
    log.classList.toggle(btn.dataset.hide, !nowActive);
  });
});

/* ── Dungeon / party selection page ── */
document.getElementById('back-btn').addEventListener('click', () => {
  showPage('inn-page');
  refreshInfoPanel();
  refreshInnExpeditionStatus();
});

document.getElementById('venture-btn').addEventListener('click', () => {
  API.dungeon.deploy();
});

/* ── Adventure page ── */
document.getElementById('watch-inn-btn').addEventListener('click', stopWatching);
document.getElementById('recall-btn').addEventListener('click', recallParty);

document.getElementById('return-btn').addEventListener('click', () => {
  document.getElementById('outcome-overlay').classList.add('hidden');
  stopWatching();
});

/* ═══════════════════════════════════════════════════════
   UI-HELPERS.JS — DOM bridges for game state changes
   Loaded BEFORE server/game/*.js so those files can call
   these as unguarded globals in the browser.
   On a real Node.js server these are replaced by WebSocket
   broadcast / REST response helpers — never loaded here.
═══════════════════════════════════════════════════════ */

/* ── Update gold amount and all gold displays ── */
function setGold(n) {
  state.gold = n;
  ['gold-amount', 'gold-amount-d', 'gold-amount-a'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.textContent = n;
  });
  // Sync dungeon affordability indicators without a full grid re-render
  if (document.getElementById('reroll-btn') && typeof _updateRerollBtn === 'function') {
    _updateRerollBtn();
  }
}

/* ── Append a message to all general event logs ── */
function addLog(msg, type = '') {
  ['event-log', 'event-log-d', 'event-log-a'].forEach(id => {
    const log = document.getElementById(id);
    if (!log) return;
    const div = document.createElement('div');
    div.className = 'log-entry' + (type ? ' ' + type : '');
    div.textContent = msg;
    log.prepend(div);
    while (log.children.length > 25) log.removeChild(log.lastChild);
  });
}

/* ── Append a message to the battle log of the watched run only ── */
function addCombatLog(run, msg, type = '', subtype = '') {
  if (!run || run.id !== state.watchingRunId) return;
  const log = document.getElementById('event-log-a');
  if (!log) return;
  const div = document.createElement('div');
  div.className = 'log-entry' + (type ? ' ' + type : '') + (subtype ? ' ' + subtype : '');
  div.textContent = msg;
  log.prepend(div);
  while (log.children.length > 80) log.removeChild(log.lastChild);
}

/* ── Show a named page, hide all others ── */
function showPage(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.add('hidden'));
  document.getElementById(id).classList.remove('hidden');
}

/* ═══════════════════════════════════════
   BASE.CSS — Reset, layout, shared components
═══════════════════════════════════════ */

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  background-color: #1a1a2e;
  font-family: Georgia, serif;
}

.hidden { display: none !important; }

.page {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  padding: 24px 16px;
  gap: 18px;
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 8px;
}
.header h1 {
  color: #e0c88a;
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-shadow: 0 0 18px rgba(224,200,138,0.4);
  white-space: nowrap;
}

/* ── Gold display ── */
.gold-display {
  background: linear-gradient(135deg, #3a2e10, #5a4820);
  border: 2px solid #c9a84c;
  border-radius: 8px;
  padding: 8px 18px;
  color: #e0c88a;
  font-size: 1.05rem;
  font-weight: bold;
  letter-spacing: 1px;
  box-shadow: 0 0 12px rgba(201,168,76,0.25);
  white-space: nowrap;
}

/* ── Mobile typography & spacing ── */
@media (max-width: 480px) {
  .page {
    padding: 16px 12px;
    gap: 14px;
  }
  /* Allow header items to wrap rather than overflow horizontally */
  .header {
    flex-wrap: wrap;
    row-gap: 6px;
  }
  .header h1 {
    font-size: 1.15rem;
    letter-spacing: 1px;
    white-space: normal;   /* override desktop nowrap */
    flex: 1 1 auto;        /* fills space between back-btn and gold; wraps text if needed */
    min-width: 0;
  }
  .gold-display {
    font-size: 0.85rem;
    padding: 6px 12px;
    flex-shrink: 0;        /* never squish the gold counter */
  }
  .section-label { font-size: 0.65rem; }
}

/* ── Event log wrapper ── */
.log-wrap {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

/* ── Expand / collapse tab ── */
.log-toggle {
  font-size: 0.58rem;
  font-family: Georgia, serif;
  letter-spacing: 0.5px;
  padding: 2px 12px;
  background: rgba(14,18,30,0.85);
  border: 1px solid #252f40;
  border-bottom: none;
  border-radius: 6px 6px 0 0;
  color: #4a6070;
  cursor: pointer;
  transition: border-color 0.15s, color 0.15s;
  user-select: none;
}
.log-toggle:hover  { border-color: #c9a84c; color: #c9a84c; }
.log-toggle.active { border-color: #c9a84c; color: #c9a84c; }

/* ── Event log ── */
.event-log {
  width: 100%;
  background: rgba(14,18,30,0.85);
  border: 1px solid #252f40;
  border-radius: 0 0 8px 8px;
  padding: 10px 14px;
  min-height: 64px;
  max-height: 80px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 0.78rem;
  transition: max-height 0.35s ease;
}
.event-log.expanded { max-height: 400px; border-radius: 8px; }
.log-entry         { color: #6a8090; }
.log-entry.gold    { color: #c9a84c; }
.log-entry.upgrade { color: #6ab0e0; }
.log-entry.dungeon { color: #e08080; }

/* ── Rarity badges (shared) ── */
.rarity-badge {
  font-size: 0.52rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  padding: 2px 7px;
  border-radius: 10px;
}
.rarity-common    { color: #9a9aaa; background: rgba(154,154,170,0.1); border: 1px solid #4a4a5a; }
.rarity-uncommon  { color: #4ac96a; background: rgba(74,201,106,0.1);  border: 1px solid #2a8a4a; }
.rarity-rare      { color: #4a9ae9; background: rgba(74,154,233,0.1);  border: 1px solid #2a5ab0; }
.rarity-epic      { color: #c04ae9; background: rgba(192,74,233,0.1);  border: 1px solid #803ab0; }
.rarity-legendary { color: #e9c84a; background: rgba(233,200,74,0.12); border: 1px solid #b09030; }

/* ── Section label ── */
.section-label {
  align-self: flex-start;
  font-size: 0.72rem;
  color: #5a7080;
  text-transform: uppercase;
  letter-spacing: 2px;
}

